template<class T>
inline T *copy_backward(T *first, T *last, T *result)
{
    while (last != first)
        *--result = *--last;
    return result;
}

template<class T>
inline void destroy(T *, T *) {}

template<class T, class Allocator>
class vector {
    T *_M_start;
    T *_M_finish;
    T *_M_end_of_storage;

    static T *allocate(unsigned int count)
    {
        unsigned int bytes = count * sizeof(T);
        if (bytes == 0)
            return 0;
        if (bytes > 128) {
            void *result = arch_malloc(bytes, allocator_description, 0);
            return (T *)(result ? result : oom_malloc(bytes));
        }
        unsigned int rounded = (bytes + 7) & ~7;
        unsigned int index = rounded / 8 - 1;
        void *result = __default_alloc_free_list[index];
        if (result == 0)
            result = refill(rounded);
        else
            __default_alloc_free_list[index] = *(void **)result;
        return (T *)result;
    }

    static void deallocate(T *pointer, unsigned int count)
    {
        unsigned int bytes = count * sizeof(T);
        if (bytes == 0)
            return;
        if (bytes > 128)
            arch_free(pointer);
        else {
            unsigned int index = ((bytes + 7) & ~7) / 8 - 1;
            *(void **)pointer = __default_alloc_free_list[index];
            __default_alloc_free_list[index] = pointer;
        }
    }

public:
    typedef T *iterator;
    typedef unsigned int size_type;

    size_type size() const { return _M_finish - _M_start; }

    void insert(iterator position, size_type n, const T &x);
};

template<class T, class Allocator>
void vector<T, Allocator>::insert(iterator position, size_type n, const T &x)
{
    if (n != 0) {
        if (size_type(_M_end_of_storage - _M_finish) >= n) {
            T x_copy = x;
            const size_type elems_after = _M_finish - position;
            iterator old_finish = _M_finish;
            if (elems_after > n) {
                uninitialized_copy(_M_finish - n, _M_finish, _M_finish);
                _M_finish += n;
                copy_backward(position, old_finish - n, old_finish);
                fill(position, position + n, x_copy);
            } else {
                uninitialized_fill_n(_M_finish, n - elems_after, x_copy);
                _M_finish += n - elems_after;
                uninitialized_copy(position, old_finish, _M_finish);
                _M_finish += elems_after;
                fill(position, old_finish, x_copy);
            }
        } else {
            const size_type old_size = size();
            const size_type len = old_size + (old_size > n ? old_size : n);
            iterator new_start = allocate(len);
            iterator new_finish = new_start;
            new_finish = uninitialized_copy(_M_start, position, new_start);
            new_finish = uninitialized_fill_n(new_finish, n, x);
            new_finish = uninitialized_copy(position, _M_finish, new_finish);
            destroy(_M_start, _M_finish);
            deallocate(_M_start, _M_end_of_storage - _M_start);
            _M_start = new_start;
            _M_finish = new_finish;
            _M_end_of_storage = new_start + len;
        }
    }
}

